mapper.select:
SELECT h.indicator_first_id AS indicatorFirstId, ci.indicator_name AS indicatorName, ci.weight AS indicatorWeight, COUNT(*) AS totalTasks, SUM(CASE WHEN hr.status IN (1, 2, 4) THEN 1 ELSE 0 END) AS submittedTasks, SUM(CASE WHEN hr.status IN (1, 4) THEN 1 ELSE 0 END) AS pendingReviewTasks, SUM(CASE WHEN hr.status = 2 AND hr.score IS NOT NULL THEN 1 ELSE 0 END) AS evaluatedTasks, SUM(CASE WHEN hr.status = 2 AND hr.score >= h.pass_score THEN 1 ELSE 0 END) AS qualifiedTasks FROM edu_homework h JOIN edu_homework_assignee ha ON ha.homework_id = h.id AND ha.student_id = #{studentId} AND ha.deleted = 0 LEFT JOIN edu_homework_record hr ON h.id = hr.homework_id AND hr.student_id = #{studentId} AND hr.deleted = 0 JOIN capacity_indicator ci ON h.indicator_first_id = ci.id AND ci.deleted = 0 WHERE h.class_id IN
#{classId}
AND h.deleted = 0 AND h.indicator_first_id IS NOT NULL GROUP BY h.indicator_first_id, ci.indicator_name, ci.weight

SELECT h.indicator_second_id AS indicatorSecondId, ci.indicator_name AS indicatorName, COUNT(*) AS totalTasks, SUM(CASE WHEN hr.status IN (1, 2, 4) THEN 1 ELSE 0 END) AS submittedTasks, SUM(CASE WHEN hr.status IN (1, 4) THEN 1 ELSE 0 END) AS pendingReviewTasks, SUM(CASE WHEN hr.status = 2 AND hr.score IS NOT NULL THEN 1 ELSE 0 END) AS evaluatedTasks, SUM(CASE WHEN hr.status = 2 AND hr.score >= h.pass_score THEN 1 ELSE 0 END) AS qualifiedTasks FROM edu_homework h JOIN edu_homework_assignee ha ON ha.homework_id = h.id AND ha.student_id = #{studentId} AND ha.deleted = 0 LEFT JOIN edu_homework_record hr ON h.id = hr.homework_id AND hr.student_id = #{studentId} AND hr.deleted = 0 JOIN capacity_indicator ci ON h.indicator_second_id = ci.id AND ci.deleted = 0 WHERE h.class_id IN
#{classId}
AND h.indicator_first_id = #{indicatorFirstId} AND h.deleted = 0 AND h.indicator_second_id IS NOT NULL GROUP BY h.indicator_second_id, ci.indicator_name

SELECT h.id AS homeworkId, h.homework_name AS homeworkName, h.indicator_second_id AS indicatorSecondId, h.pass_score AS passScore, CASE WHEN hr.status = 2 THEN hr.score ELSE NULL END AS score, hr.status AS recordStatus FROM edu_homework h JOIN edu_homework_assignee ha ON ha.homework_id = h.id AND ha.student_id = #{studentId} AND ha.deleted = 0 LEFT JOIN edu_homework_record hr ON h.id = hr.homework_id AND hr.student_id = #{studentId} AND hr.deleted = 0 WHERE h.class_id IN
#{classId}
AND h.indicator_first_id = #{indicatorFirstId} AND h.deleted = 0 ORDER BY h.id

SELECT COUNT(*) AS totalTasks, SUM(CASE WHEN hr.status IN (1,2,4) THEN 1 ELSE 0 END) AS submittedTasks, SUM(CASE WHEN hr.status IN (1,4) THEN 1 ELSE 0 END) AS pendingReviewTasks, SUM(CASE WHEN hr.status = 2 AND hr.score IS NOT NULL THEN 1 ELSE 0 END) AS evaluatedTasks, SUM(CASE WHEN hr.status = 2 AND hr.score >= h.pass_score THEN 1 ELSE 0 END) AS qualifiedTasks, SUM(CASE WHEN hr.status = 2 AND hr.score IS NOT NULL AND h.indicator_first_id IS NULL THEN 1 ELSE 0 END) AS unindicatedEvaluatedCount FROM edu_homework h JOIN edu_homework_assignee ha ON ha.homework_id = h.id AND ha.student_id = #{studentId} AND ha.deleted = 0 LEFT JOIN edu_homework_record hr ON h.id = hr.homework_id AND hr.student_id = #{studentId} AND hr.deleted = 0 WHERE h.class_id IN
#{classId}
AND h.deleted = 0

SELECT DATE(hr.correct_time) AS recordDate, SUM(SUM(hr.score)) OVER (ORDER BY DATE(hr.correct_time)) AS totalScore FROM edu_homework_record hr JOIN edu_homework h ON h.id = hr.homework_id AND h.deleted = 0 WHERE hr.student_id = #{studentId} AND hr.deleted = 0 AND hr.status = 2 AND hr.score IS NOT NULL AND hr.correct_time IS NOT NULL AND h.class_id IN
#{classId}
AND EXISTS (SELECT 1 FROM edu_homework_assignee ha WHERE ha.homework_id = h.id AND ha.student_id = #{studentId} AND ha.deleted = 0) GROUP BY DATE(hr.correct_time) ORDER BY recordDate
